let p = msg.payload;

// MQTT puede entregar Buffer, texto u objeto según la configuración.
if (Buffer.isBuffer(p)) {
    p = p.toString('utf8');
}

if (typeof p === 'string') {
    try { p = JSON.parse(p); }
    catch (e) {
        node.error('El payload MQTT no es JSON válido', msg);
        return null;
    }
}

if (!p || typeof p !== 'object') {
    node.error('Payload MQTT no válido', msg);
    return null;
}

// Formato principal esperado:
// {"latitud":40.389700,"longitud":-3.627894,"consumo":8.71}
const lat = Number(
    p.latitud ?? p.lat ?? p.latitude ??
    p.location?.latitud ?? p.location?.lat ?? p.location?.latitude ??
    p.ubicacion?.latitud ?? p.ubicacion?.lat ?? p.ubicacion?.latitude
);
const lon = Number(
    p.longitud ?? p.lon ?? p.lng ?? p.longitude ??
    p.location?.longitud ?? p.location?.lon ?? p.location?.lng ?? p.location?.longitude ??
    p.ubicacion?.longitud ?? p.ubicacion?.lon ?? p.ubicacion?.lng ?? p.ubicacion?.longitude
);
const consumo = Number(p.consumo);

if (!Number.isFinite(lat) || !Number.isFinite(lon) || lat < -90 || lat > 90 || lon < -180 || lon > 180) {
    node.error('Coordenadas no válidas. Se esperan latitud y longitud numéricas.', msg);
    return null;
}

if (!Number.isFinite(consumo) || consumo < 0) {
    node.error('Consumo no válido. Se espera consumo en L/100 km.', msg);
    return null;
}

flow.set('gps', { lat, lon, consumo, ts: Date.now() });
flow.set('consumoL100', consumo);

msg.topic = 'recalcular';
msg.payload = { lat, lon, consumo };
node.status({
    fill:'green',
    shape:'dot',
    text:`${lat.toFixed(5)}, ${lon.toFixed(5)} · ${consumo.toFixed(2)} L/100 km`
});
return msg;

msg.method = 'GET';
msg.url = 'https://energia.serviciosmin.gob.es/ServiciosRestCarburantes/PreciosCarburantes/EstacionesTerrestres/';
msg.headers = {
    Accept: 'application/json',
    'User-Agent': 'Node-RED gasolineras-dashboard'
};
msg.payload = '';
return msg;

let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) {}
}

if (!p || !Array.isArray(p.ListaEESSPrecio)) {
    node.error('La API oficial no devolvió ListaEESSPrecio', msg);
    node.status({fill:'red', shape:'ring', text:'Error descargando precios'});
    return null;
}

flow.set('estaciones', p.ListaEESSPrecio);
flow.set('fechaPrecios', p.Fecha || '');
flow.set('preciosActualizadosLocal', new Date().toISOString());

node.status({fill:'green', shape:'dot', text:`${p.ListaEESSPrecio.length} estaciones`});
msg.topic = 'recalcular';
msg.payload = { estaciones: p.ListaEESSPrecio.length, fecha: p.Fecha || '' };
return msg;

const key = String(msg.payload || '').trim();
const valid = new Set([
'g95e5','g95e10','g95e25','g95e85','g95e5premium','g98e5','g98e10',
'dieselA','dieselPremium','dieselB','glp','gnc','gnl','biogasC','biogasL',
'biodiesel','bioetanol','dieselRenovable','gasolinaRenovable','adblue','hidrogeno','amoniaco','metanol'
]);
if (!valid.has(key)) {
    node.warn('Combustible desconocido: ' + key);
    return null;
}
flow.set('combustible', key);
msg.topic = 'recalcular';
return msg;

const gps = flow.get('gps');
const estaciones = flow.get('estaciones') || [];
const selected = flow.get('combustible') || 'g95e5';

const fuels = {
    g95e5: {label:'Gasolina 95 (E5)', unit:'€/L', fields:['Precio Gasolina 95 E5','Precio_x0020_Gasolina_x0020_95_x0020_E5']},
    g95e10: {label:'Gasolina 95 E10', unit:'€/L', fields:['Precio Gasolina 95 E10','Precio_x0020_Gasolina_x0020_95_x0020_E10']},
    g95e25: {label:'Gasolina 95 E25', unit:'€/L', fields:['Precio Gasolina 95 E25','Precio_x0020_Gasolina_x0020_95_x0020_E25']},
    g95e85: {label:'Gasolina 95 E85', unit:'€/L', fields:['Precio Gasolina 95 E85','Precio_x0020_Gasolina_x0020_95_x0020_E85']},
    g95e5premium: {label:'Gasolina 95 E5 Premium', unit:'€/L', fields:['Precio Gasolina 95 E5 Premium','Precio_x0020_Gasolina_x0020_95_x0020_E5_x0020_Premium']},
    g98e5: {label:'Gasolina 98 (E5)', unit:'€/L', fields:['Precio Gasolina 98 E5','Precio_x0020_Gasolina_x0020_98_x0020_E5']},
    g98e10: {label:'Gasolina 98 E10', unit:'€/L', fields:['Precio Gasolina 98 E10','Precio_x0020_Gasolina_x0020_98_x0020_E10']},
    dieselA: {label:'Diésel / Gasóleo A', unit:'€/L', fields:['Precio Gasoleo A','Precio_x0020_Gasoleo_x0020_A']},
    dieselPremium: {label:'Diésel Premium', unit:'€/L', fields:['Precio Gasoleo Premium','Precio_x0020_Gasoleo_x0020_Premium']},
    dieselB: {label:'Gasóleo B', unit:'€/L', fields:['Precio Gasoleo B','Precio_x0020_Gasoleo_x0020_B']},
    glp: {label:'GLP', unit:'€/L', fields:['Precio Gases licuados del petróleo','Precio_x0020_Gases_x0020_licuados_x0020_del_x0020_petróleo']},
    gnc: {label:'GNC', unit:'€/kg', fields:['Precio Gas Natural Comprimido','Precio_x0020_Gas_x0020_Natural_x0020_Comprimido']},
    gnl: {label:'GNL', unit:'€/kg', fields:['Precio Gas Natural Licuado','Precio_x0020_Gas_x0020_Natural_x0020_Licuado']},
    biogasC: {label:'Biogás Natural Comprimido', unit:'€/kg', fields:['Precio Biogas Natural Comprimido','Precio_x0020_Biogas_x0020_Natural_x0020_Comprimido']},
    biogasL: {label:'Biogás Natural Licuado', unit:'€/kg', fields:['Precio Biogas Natural Licuado','Precio_x0020_Biogas_x0020_Natural_x0020_Licuado']},
    biodiesel: {label:'Biodiésel', unit:'€/L', fields:['Precio Biodiesel','Precio_x0020_Biodiesel']},
    bioetanol: {label:'Bioetanol', unit:'€/L', fields:['Precio Bioetanol','Precio_x0020_Bioetanol']},
    dieselRenovable: {label:'Diésel Renovable', unit:'€/L', fields:['Precio Diésel Renovable','Precio_x0020_Diésel_x0020_Renovable']},
    gasolinaRenovable: {label:'Gasolina Renovable', unit:'€/L', fields:['Precio Gasolina Renovable','Precio_x0020_Gasolina_x0020_Renovable']},
    adblue: {label:'AdBlue', unit:'€/L', fields:['Precio Adblue','Precio_x0020_Adblue']},
    hidrogeno: {label:'Hidrógeno', unit:'€/kg', fields:['Precio Hidrogeno','Precio_x0020_Hidrogeno']},
    amoniaco: {label:'Amoníaco', unit:'€/kg', fields:['Precio Amoniaco','Precio_x0020_Amoniaco']},
    metanol: {label:'Metanol', unit:'€/L', fields:['Precio Metanol','Precio_x0020_Metanol']}
};

const fuel = fuels[selected] || fuels.g95e5;
const consumo = gps && Number.isFinite(gps.consumo) ? gps.consumo : Number(flow.get('consumoL100'));
const canCalculateEuro100 = fuel.unit === '€/L' && Number.isFinite(consumo);

const basePayload = {
    selectedFuel: selected,
    fuelLabel: fuel.label,
    unit: fuel.unit,
    consumoL100: Number.isFinite(consumo) ? consumo : null,
    canCalculateEuro100,
    top3: [],
    gps: gps || null,
    fechaPrecios: flow.get('fechaPrecios') || '',
    preciosActualizadosLocal: flow.get('preciosActualizadosLocal') || '',
    state: 'ok',
    message: '',
    consumoMessage: ''
};

if (!gps || !Number.isFinite(gps.lat) || !Number.isFinite(gps.lon)) {
    basePayload.state = 'waiting-gps';
    basePayload.message = 'Esperando MQTT: {latitud, longitud, consumo}.';
    msg.payload = basePayload;
    return msg;
}

if (!Number.isFinite(consumo)) {
    basePayload.state = 'waiting-consumption';
    basePayload.message = 'La ubicación ha llegado, pero falta consumo en L/100 km.';
    msg.payload = basePayload;
    return msg;
}

if (!estaciones.length) {
    basePayload.state = 'waiting-prices';
    basePayload.message = 'Descargando precios oficiales…';
    msg.payload = basePayload;
    return msg;
}

if (fuel.unit !== '€/L') {
    basePayload.consumoMessage = `El consumo MQTT es ${consumo.toFixed(2)} L/100 km, pero ${fuel.label} se publica en ${fuel.unit}. No se puede obtener €/100 km sin un consumo compatible.`;
}

function first(obj, names) {
    for (const n of names) {
        if (obj[n] !== undefined && obj[n] !== null && String(obj[n]).trim() !== '') return obj[n];
    }
    return '';
}

function num(v) {
    if (v === undefined || v === null || v === '') return NaN;
    return Number(String(v).trim().replace(',', '.'));
}

function distanceKm(lat1, lon1, lat2, lon2) {
    const R = 6371;
    const dLat = (lat2-lat1) * Math.PI / 180;
    const dLon = (lon2-lon1) * Math.PI / 180;
    const a =
        Math.sin(dLat/2)**2 +
        Math.cos(lat1*Math.PI/180) *
        Math.cos(lat2*Math.PI/180) *
        Math.sin(dLon/2)**2;
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const rows = [];

for (const e of estaciones) {
    const lat = num(first(e, ['Latitud']));
    const lon = num(first(e, ['Longitud (WGS84)','Longitud_x0020__x0028_WGS84_x0029_']));

    if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    if (lat < -90 || lat > 90 || lon < -180 || lon > 180) continue;

    const distanciaKm = distanceKm(gps.lat, gps.lon, lat, lon);

    const rawPrice = first(e, fuel.fields);
    const parsedPrice = num(rawPrice);
    const disponible = Number.isFinite(parsedPrice) && parsedPrice > 0;
    const price = disponible ? parsedPrice : null;

    const costeEuro100 =
        disponible && canCalculateEuro100
            ? consumo * price
            : null;

    rows.push({
        id: String(first(e, ['IDEESS']) || `${lat},${lon}`),
        nombre: String(first(e, ['Rótulo','Rotulo']) || 'Gasolinera'),
        direccion: String(first(e, ['Dirección','Direccion']) || ''),
        localidad: String(first(e, ['Localidad']) || ''),
        municipio: String(first(e, ['Municipio']) || ''),
        provincia: String(first(e, ['Provincia']) || ''),
        horario: String(first(e, ['Horario']) || ''),
        lat,
        lon,
        price,
        disponible,
        consumoL100: consumo,
        costeEuro100,
        distanciaKm
    });
}

// IMPORTANTE:
// El TOP 3 se calcula SOLO por distancia geográfica.
// Después se comprueba si cada una vende el combustible seleccionado.
rows.sort((a,b) => a.distanciaKm - b.distanciaKm);
basePayload.top3 = rows.slice(0,3);

basePayload.availableCount = rows.filter(r => r.disponible).length;
basePayload.nearestDistanceKm = basePayload.top3.length ? basePayload.top3[0].distanciaKm : null;

if (!basePayload.top3.length) {
    basePayload.state = 'no-results';
    basePayload.message = 'No se han encontrado estaciones con coordenadas válidas.';
} else if (!basePayload.top3.some(r => r.disponible)) {
    basePayload.message = `Las 3 estaciones más cercanas no publican precio para ${fuel.label}.`;
}

// Diagnóstico útil en DEBUG TOP 3 / estado
basePayload.debugGps = {
    latitudUsada: gps.lat,
    longitudUsada: gps.lon,
    consumoUsado: consumo
};

node.status({
    fill: basePayload.top3.length ? 'green' : 'yellow',
    shape:'dot',
    text:`GPS ${gps.lat.toFixed(4)}, ${gps.lon.toFixed(4)} · nearest ${basePayload.nearestDistanceKm !== null ? basePayload.nearestDistanceKm.toFixed(2)+' km' : '—'}`
});

msg.payload = basePayload;
return msg;

const p = msg.payload || {};
const out = [];

// ======================================================
// ICONOS
// ======================================================

// Worldmap permite usar emojis con la sintaxis :emoji:
const iconosTop = [
    ":1️⃣:",
    ":2️⃣:",
    ":3️⃣:"
];

// ======================================================
// 1. LIMPIAR CAPAS
// ======================================================

out.push({
    payload: {
        command: {
            clearlayer: [
                "Gasolineras TOP 3",
                "Mi ubicación"
            ]
        }
    }
});

// ======================================================
// 2. MI UBICACIÓN
// ======================================================

if (
    p.gps &&
    Number.isFinite(Number(p.gps.lat)) &&
    Number.isFinite(Number(p.gps.lon))
) {

    const lat = Number(p.gps.lat);
    const lon = Number(p.gps.lon);

    let popup =
        "<b>🚗 Mi ubicación</b><br>" +
        "Latitud: " + lat.toFixed(6) + "<br>" +
        "Longitud: " + lon.toFixed(6);

    if (Number.isFinite(Number(p.consumoL100))) {
        popup +=
            "<br><br>⛽ Consumo: <b>" +
            Number(p.consumoL100).toFixed(2) +
            " L/100 km</b>";
    }

    out.push({
        payload: {
            name: "Mi ubicación",

            lat: lat,
            lon: lon,

            layer: "Mi ubicación",

            // ICONO DE TU POSICIÓN
            icon: ":🚗:",

            tooltip: "Mi ubicación",

            popup: popup,

            ttl: 0
        }
    });
}

// ======================================================
// 3. TOP 3 GASOLINERAS
// ======================================================

const top3 = Array.isArray(p.top3)
    ? p.top3
    : [];

for (let i = 0; i < top3.length; i++) {

    const g = top3[i];

    const lat = Number(g.lat);
    const lon = Number(g.lon);

    if (
        !Number.isFinite(lat) ||
        !Number.isFinite(lon)
    ) {
        node.warn(
            "Gasolinera sin coordenadas: " +
            JSON.stringify(g)
        );
        continue;
    }

    // ==================================================
    // DISTANCIA
    // ==================================================

    const dist =
        Number.isFinite(Number(g.distanciaKm))
            ? Number(g.distanciaKm).toLocaleString(
                "es-ES",
                {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2
                }
            )
            : "—";

    // ==================================================
    // PRECIO
    // ==================================================

    const tienePrecio =
        g.disponible === true &&
        g.price !== null &&
        Number.isFinite(Number(g.price));

    const precio =
        tienePrecio
            ? Number(g.price).toLocaleString(
                "es-ES",
                {
                    minimumFractionDigits: 3,
                    maximumFractionDigits: 3
                }
            )
            : null;

    // ==================================================
    // COSTE €/100KM
    // ==================================================

    const coste =
        g.costeEuro100 !== null &&
            Number.isFinite(Number(g.costeEuro100))
            ? Number(g.costeEuro100).toLocaleString(
                "es-ES",
                {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2
                }
            )
            : null;

    // ==================================================
    // POPUP
    // ==================================================

    let popup =
        "<div style='min-width:230px'>" +

        "<h3 style='margin:0 0 10px 0'>" +
        "#" + (i + 1) + " " +
        (g.nombre || "Gasolinera") +
        "</h3>" +

        "📍 Distancia: <b>" +
        dist +
        " km</b><br><br>" +

        "⛽ " +
        (p.fuelLabel || "Combustible") +
        ":<br>";

    if (tienePrecio) {

        popup +=
            "<span style='" +
            "font-size:22px;" +
            "font-weight:bold;" +
            "'>" +

            precio +
            " " +
            (p.unit || "") +

            "</span>";

    } else {

        popup +=
            "<b>Precio no disponible</b>";
    }

    // ==================================================
    // COSTE
    // ==================================================

    if (coste !== null) {

        popup +=
            "<br><br>" +

            "🚗 Coste:<br>" +

            "<span style='" +
            "font-size:20px;" +
            "font-weight:bold;" +
            "'>" +

            coste +
            " €/100 km" +

            "</span>";

        if (
            Number.isFinite(Number(g.consumoL100)) &&
            tienePrecio
        ) {

            popup +=
                "<br><small>" +

                Number(g.consumoL100).toFixed(2) +
                " L/100 km × " +

                Number(g.price).toFixed(3) +
                " €/L" +

                "</small>";
        }
    }

    // ==================================================
    // DIRECCIÓN
    // ==================================================

    if (g.direccion) {
        popup +=
            "<br><br>📌 " +
            g.direccion;
    }

    if (g.localidad) {
        popup +=
            "<br>" +
            g.localidad;
    }

    if (g.horario) {
        popup +=
            "<br><br>🕒 " +
            g.horario;
    }

    popup += "</div>";

    // ==================================================
    // MARCADOR
    // ==================================================

    out.push({
        payload: {

            name:
                "TOP" +
                (i + 1) +
                "-" +
                String(g.id || i),

            lat: lat,
            lon: lon,

            layer: "Gasolineras TOP 3",

            // AQUÍ ESTÁ EL CAMBIO IMPORTANTE
            icon: iconosTop[i],

            tooltip:
                "#" +
                (i + 1) +
                " " +
                (g.nombre || "Gasolinera") +
                " · " +
                dist +
                " km",

            popup: popup,

            ttl: 0
        }
    });
}

// ======================================================
// 4. CENTRAR MAPA
// ======================================================

if (
    p.gps &&
    Number.isFinite(Number(p.gps.lat)) &&
    Number.isFinite(Number(p.gps.lon))
) {

    out.push({
        payload: {
            command: {

                lat: Number(p.gps.lat),
                lon: Number(p.gps.lon),

                zoom: 14,

                showlayer: [
                    "Mi ubicación",
                    "Gasolineras TOP 3"
                ]
            }
        }
    });
}

return [out];

// El worldmap-in emite msg.payload.action = "connected" cuando se abre la página.
// Recalculamos usando GPS, precios y combustible guardados en flow context.
msg.topic = "recalcular-mapa";
return msg;

// Acepta {"estado":"online"} (firmware) y también texto plano
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { /* texto plano */ }
}

const valor = (p && typeof p === 'object') ? p.estado : p;
const estado = String(valor || '').trim().toLowerCase();

if (estado !== 'online' && estado !== 'offline') {
    node.warn('Estado desconocido: ' + estado);
    return null;
}

node.status({
    fill: estado === 'online' ? 'green' : 'red',
    shape: 'dot',
    text: estado
});

msg.payload = estado;
return msg;
